UPDATE carrier_evidence SET official_source_url = 'https://developers.usps.com/', public_disclosure = 'USPS-owned Developer Portal documents Tracking API, OAuth 2.0 onboarding and CAT/live environments. Separate 2026 access-control and account onboarding rules apply; ExportFlow''s service-provider approval and Mailer-ID scope are unconfirmed.', research_notes = '2026-11-07 source check: USPS Developer Portal lists a Tracking API and describes OAuth 2.0, self-service app registration and test environments. USPS Getting Started requires a USPS Business Account, onboarding portal setup, an application and acceptance of Terms and Conditions/Privacy Policy. USPS API Access guidance also documents 2026 access-control changes; merchant/service-provider authorization and Mailer ID access must be assessed for the proposed use. No ExportFlow approval or authorization is recorded.', evidence_status = 'research', verification_method = 'none', verified_at = NULL, verification_evidence_url = NULL, authorization_evidence_url = NULL, updated_at = CURRENT_TIMESTAMP WHERE provider_id = 'usps';

UPDATE carrier_evidence SET official_source_url = 'https://developer.postnl.nl/integration-with-postnl/api-overview/send-and-track/shippingstatus-webservice/', public_disclosure = 'PostNL-owned ShippingStatus API docs were retrieved. Returned events are restricted to matching the customer''s own customer number and parcel code; API is not a generic public tracking entitlement.', research_notes = '2026-11-07 live source check: official PostNL API documentation identifies ShippingStatus with current and full parcel status, updated-shipment retrieval by customer number, API-key and sandbox navigation. The page explicitly states disclosure is restricted to a match between customer data and parcel identifiers, and advises relevant single queries rather than frequent full polling. Existing own-shipments/customer-code scope remains; no independent third-party display permission for ExportFlow is recorded.', evidence_status = 'research', verification_method = 'none', verified_at = NULL, verification_evidence_url = NULL, authorization_evidence_url = NULL, updated_at = CURRENT_TIMESTAMP WHERE provider_id = 'postnl';

UPDATE carrier_evidence SET official_source_url = 'https://developer.dpdgroup.com/', public_disclosure = 'Geopost-owned API Portal was retrieved and lists DPD API products, including public and restricted API categories. The portal does not establish a global integration across all national DPD operators.', research_notes = '2026-11-07 source check: official Geopost API Portal is live and exposes product categories including public APIs, RMP and other DPD services. This establishes the group portal and API catalogue, but API availability, credentials, country entity, and approval differ by product/national operation. Do not convert a DPD source record into one global live adapter or claim third-party display rights.', evidence_status = 'research', verification_method = 'none', verified_at = NULL, verification_evidence_url = NULL, authorization_evidence_url = NULL, updated_at = CURRENT_TIMESTAMP WHERE provider_id = 'dpd-geopost';

