UPDATE carrier_evidence SET official_source_url = 'https://www.singpost.com/track-items', public_disclosure = 'SingPost-owned Track Your Item page and tracking help article were retrieved. They confirm consumer tracking for specified SingPost services but do not establish a developer tracking API.', research_notes = '2026-11-07 live source check: SingPost''s official Track Your Item page provides a tracking-number form; its support article identifies smartpac, Registered Service and Speedpost tracking coverage. No official developer tracking API was identified in this pass. Treat the source as an official public tracker, not authorization to automate the page or redistribute third-party shipment information.', evidence_status = 'research', verification_method = 'none', verified_at = NULL, verification_evidence_url = NULL, authorization_evidence_url = NULL, updated_at = CURRENT_TIMESTAMP WHERE provider_id = 'singapore-post';

