UPDATE carrier_evidence SET official_source_url = 'https://open.gfn.cainiao.com/apiInfo/introduce', public_disclosure = 'Cainiao Global Fulfilment Open Platform documentation describes logistics APIs including tracking and a separate software-service-provider path with customer authorization. Cainiao''s public global tracker is not itself an API license.', research_notes = '2026-11-07 source check: official Cainiao Open Platform description states that it provides logistics APIs including tracking, pickup and delivery; it distinguishes contracted merchants from software service providers and describes software providers connecting to seller accounts through customer authorization. The separate global.cainiao.com tracker is an official consumer tracking site. This confirms official API documentation and an authorization workflow, not ExportFlow approval, credentials or rights to display seller shipment data.', evidence_status = 'research', verification_method = 'none', verified_at = NULL, verification_evidence_url = NULL, authorization_evidence_url = NULL, updated_at = CURRENT_TIMESTAMP WHERE provider_id = 'cainiao';
